with flattened as (select id, host, level, latency_ms, status_code, attr_key, v from app_logs lateral view explode(context) x as attr_key, v) select case when latency_ms >= 1968 then 'HIGH' else 'LOW' end as latency_ms_tier, stddev_samp(status_code) as status_code_stddev, percentile_approx(latency_ms, 0.5) as latency_ms_p50 from flattened group by case when latency_ms >= 1968 then 'HIGH' else 'LOW' end having stddev_samp(status_code) > 0
